    test(`${kind}/${point}: an in-place ability ID change cannot redirect a pending role inspection`, async () => {
      const game = fixture(kind),
        events: GameEvent[] = [];
      let calls = 0;
      const ctx = context(game, events, async (request) => {
        calls++;
