export const PSYCHIC_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Psychic,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("psychic"),
    skillBrief: text("zh-CN", "role.psychic.brief"),
  },
  runtime: {
